input sr_req;
input ref_req;
output sr_ack;
output ref_ack;
input burst;
output [13:0] O_ddr_addr;
output [2:0] O_ddr_ba;
output O_ddr_cs_n;
output O_ddr_ras_n;
output O_ddr_cas_n;
